(function () {
  var SKIP = { k: 1, emoji: 1, src: 1, id: 1, icone: 1, couv: 1, correct: 1, aere: 1, type_: 1 };
  function tr(x, pref, i, sub) {
    if (typeof x === "string") { if (!x.trim()) return x; var e = TR_G8N[pref + "|" + sub.join(".")]; return (e && e[0] === x && e[i + 1]) ? e[i + 1] : x; }
    if (Array.isArray(x)) return x.map(function (v, j) { return tr(v, pref, i, sub.concat(j)); });
    if (x && typeof x === "object") { var o = {}; for (var k in x) o[k] = SKIP[k] ? x[k] : tr(x[k], pref, i, sub.concat(k)); return o; }
    return x;
  }
  function walk(o, id, path) {
    if (!o || typeof o !== "object") return;
    if (!Array.isArray(o) && "fr" in o && Object.keys(o).length === 1) { TR_LG.forEach(function (lg, i) { o[lg] = tr(o.fr, id + "|" + path.join("."), i, []); }); return; }
    for (var k in o) { if (k === "src" || k === "couv") continue; walk(o[k], id, path.concat(k)); }
  }
  COURS.forEach(function (c) { walk(c, c.id, []); });
})();
